insert into kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, source, year, exam_body, stem, options, correct_option, explanation, lifecycle_state, distractor_rationale) values
($q$chemistry_0201$q$, $q$Chemistry$q$, $q$Acids, Bases & Salts$q$, $q$Qualitative Analysis of Ions$q$, $q$Identify an unknown salt from a sequence of qualitative test results.$q$, $q$[{"conceptId": "kv2dlm", "weight": 1}]$q$::jsonb, 3, $q$analysis$q$, 75, $q$medium$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Na2CO3 is itself a carbonate, not an acid — it would react WITH acid to release CO2, not release CO2 into Na2CO3.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "NaHCO3 is a carbonate salt too — it would react with a stronger acid to give CO2, but its own solution is mildly alkaline, not acidic enough to turn litmus red.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Na2SO3 gives a white BaCl2 precipitate that DISSOLVES in dilute HCl (releasing SO2) — the clue that it survives dilute HCl rules this out.", "misconceptionId": "missing_prerequisite"}, {"option": "E", "explanation": "Na2SO4 is a neutral salt — its solution does not turn litmus red, so it fails the very first clue.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$X is crystalline salt of sodium. Solution of X in water turns litmus red, produces a gas which turns lime water milky when added to sodium carbonate. With barium chloride solution, X gives a white precipitate which is insoluble in dilute hydrochloric acid. X is$q$, $q$[{"label": "A", "text": "Na2CO3", "isCorrect": false}, {"label": "B", "text": "NaHCO3", "isCorrect": false}, {"label": "C", "text": "NaHSO4", "isCorrect": true}, {"label": "D", "text": "Na2SO3", "isCorrect": false}, {"label": "E", "text": "Na2SO4", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Work this one from the clues, not the options. "Turns litmus red" tells you X is acidic in solution — that already rules out Na2SO4, which is neutral. "Gas that turns limewater milky when added to Na2CO3" means X released CO2 from the carbonate, which only happens if X itself is acting as an acid. Then the BaCl2 test: a white precipitate that survives dilute HCl is the sulphate signature — sulphites and carbonates give the same white precipitate, but theirs redissolves in the acid. Put the three clues together and NaHSO4 is the only option that's both acidic and a genuine sulphate.$q$, $q$live$q$, $q$A: Na2CO3 is itself a carbonate, not an acid — it would react WITH acid to release CO2, not release CO2 into Na2CO3. B: NaHCO3 is a carbonate salt too — it would react with a stronger acid to give CO2, but its own solution is mildly alkaline, not acidic enough to turn litmus red. D: Na2SO3 gives a white BaCl2 precipitate that DISSOLVES in dilute HCl (releasing SO2) — the clue that it survives dilute HCl rules this out. E: Na2SO4 is a neutral salt — its solution does not turn litmus red, so it fails the very first clue.$q$),
($q$chemistry_0202$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Alkanols and Soap Chemistry (Saponification)$q$, $q$Identify the alkanol byproduct of soap manufacture.$q$, $q$[{"conceptId": "z9kmjm", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 30, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Ethanol is the alkanol produced by fermenting sugars, not the one released when a fat ester is broken apart by an alkali.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Methanol has no role in saponification — it's a distractor built from another common alkanol, not the actual byproduct.", "misconceptionId": "memorized_not_understood"}, {"option": "D", "explanation": "Propanol has no role in saponification — fats are esters of glycerol specifically, not propanol.", "misconceptionId": "memorized_not_understood"}, {"option": "E", "explanation": "Glycol (ethylene glycol) is a different diol entirely, unrelated to the fat-hydrolysis product of soap making.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$The alkanol obtained from the production of soap is$q$, $q$[{"label": "A", "text": "ethanol", "isCorrect": false}, {"label": "B", "text": "glycerol", "isCorrect": true}, {"label": "C", "text": "methanol", "isCorrect": false}, {"label": "D", "text": "propanol", "isCorrect": false}, {"label": "E", "text": "glycol", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Soap making (saponification) is fat or oil reacting with a strong alkali. The fat itself is an ester of glycerol, so when the alkali breaks that ester apart, you get the soap (the salt of the fatty acid) and glycerol as the byproduct. Glycerol is the alkanol here because it's the one with the -OH groups left over.$q$, $q$live$q$, $q$A: Ethanol is the alkanol produced by fermenting sugars, not the one released when a fat ester is broken apart by an alkali. C: Methanol has no role in saponification — it's a distractor built from another common alkanol, not the actual byproduct. D: Propanol has no role in saponification — fats are esters of glycerol specifically, not propanol. E: Glycol (ethylene glycol) is a different diol entirely, unrelated to the fat-hydrolysis product of soap making.$q$),
($q$chemistry_0203$q$, $q$Chemistry$q$, $q$Chemistry & Industry$q$, $q$Welding and Metalworking Flames$q$, $q$Identify the flame used for cutting/welding metal.$q$, $q$[{"conceptId": "jv7ln2", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Butane gas doesn't burn hot enough on its own to cut metal — it's a household/portable-torch fuel, not a welding fuel.", "misconceptionId": "memorized_not_understood"}, {"option": "B", "explanation": "Acetylene alone, without the extra oxygen, burns far cooler in ordinary air than the oxy-acetylene mixture — the oxygen is what pushes the temperature high enough to cut metal.", "misconceptionId": "missing_prerequisite"}, {"option": "C", "explanation": "Kerosene is a heating/lighting fuel, not a welding gas — it doesn't reach metal-cutting temperatures.", "misconceptionId": "memorized_not_understood"}, {"option": "E", "explanation": "Oxygen alone is not a fuel — it supports combustion but has nothing to burn without acetylene.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$The flame used by welders in cutting metals is$q$, $q$[{"label": "A", "text": "butane gas flame", "isCorrect": false}, {"label": "B", "text": "acetylene flame", "isCorrect": false}, {"label": "C", "text": "kerosene flame", "isCorrect": false}, {"label": "D", "text": "oxy-acetylene flame", "isCorrect": true}, {"label": "E", "text": "oxygen flame", "isCorrect": false}]$q$::jsonb, $q$D$q$, $q$This is a straight recall fact: oxy-acetylene flames burn hot enough (over 3000°C) to melt through metal cleanly, which is exactly what welders need for cutting and joining. Acetylene alone doesn't burn hot enough without the extra oxygen boosting the flame temperature.$q$, $q$live$q$, $q$A: Butane gas doesn't burn hot enough on its own to cut metal — it's a household/portable-torch fuel, not a welding fuel. B: Acetylene alone, without the extra oxygen, burns far cooler in ordinary air than the oxy-acetylene mixture — the oxygen is what pushes the temperature high enough to cut metal. C: Kerosene is a heating/lighting fuel, not a welding gas — it doesn't reach metal-cutting temperatures. E: Oxygen alone is not a fuel — it supports combustion but has nothing to burn without acetylene.$q$),
($q$chemistry_0204$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Hydrocarbons — Homologous Series$q$, $q$State the formula difference between consecutive members of the alkane homologous series.$q$, $q$[{"conceptId": "r4t0dz", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "CH would mean adding one carbon and only one hydrogen — checking real consecutive alkanes (CH4 to C2H6) shows two hydrogens are added, not one.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "CH3 would mean adding one carbon and three hydrogens — one hydrogen too many compared to the real CH2 step.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "CnHn is not even a valid alkane general formula (real alkanes are CnH2n+2) — it's a distractor built from a plausible-looking but wrong pattern.", "misconceptionId": "misunderstood_terminology"}, {"option": "E", "explanation": "CnH2n+2 is the alkane GENERAL formula, not the DIFFERENCE between two consecutive members — a common mix-up between 'the formula of a member' and 'the step between members'.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$Consecutive members of an alkane homologous series differ by$q$, $q$[{"label": "A", "text": "CH", "isCorrect": false}, {"label": "B", "text": "CH2", "isCorrect": true}, {"label": "C", "text": "CH3", "isCorrect": false}, {"label": "D", "text": "CnHn", "isCorrect": false}, {"label": "E", "text": "CnH2n+2", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$This one is testing whether you know what a homologous series actually does. Members of a homologous series differ from one another by CH2 — methane to ethane, ethane to propane, each step adds one carbon and two hydrogens. Same idea for alkanols, alkanoic acids, and every other homologous series. Quick trick if you ever forget: write out the first two or three members and compare them — the difference should be CH2.$q$, $q$live$q$, $q$A: CH would mean adding one carbon and only one hydrogen — checking real consecutive alkanes (CH4 to C2H6) shows two hydrogens are added, not one. C: CH3 would mean adding one carbon and three hydrogens — one hydrogen too many compared to the real CH2 step. D: CnHn is not even a valid alkane general formula (real alkanes are CnH2n+2) — it's a distractor built from a plausible-looking but wrong pattern. E: CnH2n+2 is the alkane GENERAL formula, not the DIFFERENCE between two consecutive members — a common mix-up between 'the formula of a member' and 'the step between members'.$q$),
($q$chemistry_0205$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Electronic Configuration and Periodic Blocks$q$, $q$Determine an element's periodic block from its electronic configuration.$q$, $q$[{"conceptId": "7u41s5", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 55, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Silicon (the element this configuration identifies) is a metalloid, not a straightforward metal — this option overgeneralizes 'has some electrons in outer shells' into 'is a metal'.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "Alkaline earth metals are group 2, s-block elements ending in ns2 with no p electrons — this configuration's outer p electrons rule that out.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "s-block elements have their last electron enter an s subshell — this configuration's last electrons are in 3p, not 3s, so it's not s-block.", "misconceptionId": "misunderstood_terminology"}, {"option": "E", "explanation": "Transition elements have their last electron enter a d subshell — this configuration has no d electrons at all.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$If an element has the electronic configuration 1s2 2s2 2p6 3s2 3p2, it is$q$, $q$[{"label": "A", "text": "a metal", "isCorrect": false}, {"label": "B", "text": "an alkaline earth metal", "isCorrect": false}, {"label": "C", "text": "an s-block element", "isCorrect": false}, {"label": "D", "text": "a p-block element", "isCorrect": true}, {"label": "E", "text": "a transition element", "isCorrect": false}]$q$::jsonb, $q$D$q$, $q$Count the electrons first: 2+2+6+2+2 = 14 — that's silicon. The block an element belongs to is decided by where its last electron goes, not by adding up all the electrons. Silicon's outermost electrons are in 3p, so it's a p-block element. It's not an alkaline earth metal (that's group 2, s-block) and it's not even really a metal — silicon is a metalloid.$q$, $q$live$q$, $q$A: Silicon (the element this configuration identifies) is a metalloid, not a straightforward metal — this option overgeneralizes 'has some electrons in outer shells' into 'is a metal'. B: Alkaline earth metals are group 2, s-block elements ending in ns2 with no p electrons — this configuration's outer p electrons rule that out. C: s-block elements have their last electron enter an s subshell — this configuration's last electrons are in 3p, not 3s, so it's not s-block. E: Transition elements have their last electron enter a d subshell — this configuration has no d electrons at all.$q$),
($q$chemistry_0206$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Hydrates and Water of Crystallization$q$, $q$Determine how many water molecules were lost from a hydrate using mass-loss data.$q$, $q$[{"conceptId": "sdx4xa", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 80, $q$medium$q$, $q$heavy$q$, $q$[{"option": "A", "explanation": "This badly understates the water lost — it looks like a single-step-formula shortcut that skips computing the actual mole ratio from the mass data.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "This undercounts by using too little of the 1.44g mass loss when converting to moles of water.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "Close, but still short of the real ratio (0.08/0.02=4) — a rounding or division slip along the way.", "misconceptionId": "arithmetic_slip"}, {"option": "E", "explanation": "This assumes ALL the water of crystallization left the salt — but the mass-loss data shows only 4 of the 5 molecules actually escaped at 120°C, not the full formula amount.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$Some copper (II) sulphate pentahydrate (CuSO4.5H2O), was heated at 120°C with the following results: Wt of crucible = 10.00 g; Wt of crucible + CuSO4.5H2O = 14.98g; Wt of crucible + residue = 13.54g. How many molecules of water of crystallization were lost? [H=1, Cu=63.5, O=16, S=32]$q$, $q$[{"label": "A", "text": "1", "isCorrect": false}, {"label": "B", "text": "2", "isCorrect": false}, {"label": "C", "text": "3", "isCorrect": false}, {"label": "D", "text": "4", "isCorrect": true}, {"label": "E", "text": "5", "isCorrect": false}]$q$::jsonb, $q$D$q$, $q$Let's take this step by step. The hydrate started at 4.98g (14.98 - 10.00) and after heating, 3.54g remained (13.54 - 10.00). So the mass that left was water: 4.98 - 3.54 = 1.44g. Convert that to moles: 1.44 / 18 = 0.08 mol H2O. Next, find the moles of CuSO4.5H2O you started with: 4.98 / 249.5 ≈ 0.02 mol. Now compare them: 0.08 / 0.02 = 4. So 4 mol of water left per mol of CuSO4 — meaning only 4 of the 5 water molecules were lost, not all of them. The important habit: whenever a hydrate is heated, don't assume all its water left. Use the mass lost to work out how many molecules actually escaped.$q$, $q$live$q$, $q$A: This badly understates the water lost — it looks like a single-step-formula shortcut that skips computing the actual mole ratio from the mass data. B: This undercounts by using too little of the 1.44g mass loss when converting to moles of water. C: Close, but still short of the real ratio (0.08/0.02=4) — a rounding or division slip along the way. E: This assumes ALL the water of crystallization left the salt — but the mass-loss data shows only 4 of the 5 molecules actually escaped at 120°C, not the full formula amount.$q$),
($q$chemistry_0207$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Molecular Shape$q$, $q$Recall the 3D molecular shape of methane.$q$, $q$[{"conceptId": "cl4iqu", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Hexagonal shapes describe 6-membered ring systems (like benzene), not a single central carbon with 4 bonds.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Trigonal (planar) shape belongs to a central atom with 3 bonding regions, not methane's 4.", "misconceptionId": "missing_prerequisite"}, {"option": "C", "explanation": "Linear shape belongs to a central atom with only 2 bonding regions and no lone pairs — methane has 4.", "misconceptionId": "missing_prerequisite"}, {"option": "E", "explanation": "Cubical isn't a real VSEPR molecular shape at all — it's a plausible-sounding but non-existent geometry for 4 bonding pairs.", "misconceptionId": "memorized_not_understood"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$The three-dimensional shape of methane is$q$, $q$[{"label": "A", "text": "hexagonal", "isCorrect": false}, {"label": "B", "text": "trigonal", "isCorrect": false}, {"label": "C", "text": "linear", "isCorrect": false}, {"label": "D", "text": "tetrahedral", "isCorrect": true}, {"label": "E", "text": "cubical", "isCorrect": false}]$q$::jsonb, $q$D$q$, $q$Methane's carbon has four single bonds and no lone pairs, so the four bonding pairs spread out as far from each other as possible — that arrangement is tetrahedral, with bond angles around 109.5°. Any central atom with 4 bonding pairs and 0 lone pairs gives you this same shape.$q$, $q$live$q$, $q$A: Hexagonal shapes describe 6-membered ring systems (like benzene), not a single central carbon with 4 bonds. B: Trigonal (planar) shape belongs to a central atom with 3 bonding regions, not methane's 4. C: Linear shape belongs to a central atom with only 2 bonding regions and no lone pairs — methane has 4. E: Cubical isn't a real VSEPR molecular shape at all — it's a plausible-sounding but non-existent geometry for 4 bonding pairs.$q$),
($q$chemistry_0208$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Carbohydrates — Identification and Formula$q$, $q$Trace a multi-step reaction sequence starting from an unknown carbohydrate to identify the final ester product.$q$, $q$[{"conceptId": "d1sp6r", "weight": 1}]$q$::jsonb, 3, $q$analysis$q$, 85, $q$high$q$, $q$light$q$, $q$[{"option": "A", "explanation": "A soap comes from a fat/oil reacting with an alkali, not from an alkanol reacting with an alkanoic acid.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "An oil is the starting material for soap-making, unrelated to the alkanol-plus-alkanoic-acid reaction described here.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "An alkane has no oxygen-containing functional group at all — it can't come from an alkanol reacting with an acid.", "misconceptionId": "missing_prerequisite"}, {"option": "E", "explanation": "Sucrose is the original sugar type, not the small, sweet-smelling product of an ethanol + ethanoic acid reaction — this confuses the passage's starting material family with its final product.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$Questions 8-10 are based on the following: An unknown organic compound X has a relative molecular mass of 180. It is a colourless crystalline solid, readily soluble in water. X contains the element C, H, and O in the atomic ratio 1:2:1. The compound has a sweet taste and melts on heating. In the presence of yeast and in the absence of air X is converted to compound Y and a colourless gas. Compound Y reacts with sodium metal to produce a gas Z which gives a 'pop' sound with a glowing splint. Y also reacts with ethanoic acid to give a sweet-smelling compound W. Compound W is$q$, $q$[{"label": "A", "text": "a soap", "isCorrect": false}, {"label": "B", "text": "an oil", "isCorrect": false}, {"label": "C", "text": "an alkane", "isCorrect": false}, {"label": "D", "text": "an ester", "isCorrect": true}, {"label": "E", "text": "sucrose", "isCorrect": false}]$q$::jsonb, $q$D$q$, $q$Work through the chain: X is glucose (C:H:O = 1:2:1, RMM 180, sweet, water-soluble — classic glucose fingerprint). Fermented by yeast without air, glucose gives Y (ethanol) and CO2. Y reacting with sodium releasing a gas is ethanol's -OH group reacting with Na, giving off hydrogen. Then Y (ethanol) reacting with ethanoic acid — an alkanol plus an alkanoic acid — is a straight esterification, and that always gives you an ester plus water. W is the sweet-smelling ester.$q$, $q$live$q$, $q$A: A soap comes from a fat/oil reacting with an alkali, not from an alkanol reacting with an alkanoic acid. B: An oil is the starting material for soap-making, unrelated to the alkanol-plus-alkanoic-acid reaction described here. C: An alkane has no oxygen-containing functional group at all — it can't come from an alkanol reacting with an acid. E: Sucrose is the original sugar type, not the small, sweet-smelling product of an ethanol + ethanoic acid reaction — this confuses the passage's starting material family with its final product.$q$),
($q$chemistry_0209$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Carbohydrates — Identification and Formula$q$, $q$Use an atomic ratio and molar mass together to fix a molecular formula.$q$, $q$[{"conceptId": "d1sp6r", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 55, $q$medium$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "C12H22O11 is sucrose's formula (RMM 342), not a 1:2:1 ratio compound with RMM 180 — this is a distractor swapping in a different, related sugar.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "C3H6O3 keeps the correct 1:2:1 ratio but only has RMM 90 — half of the required 180, so the scaling step was stopped too early.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "C7H14O7 does not actually keep a clean 1:2:1 C:H:O ratio at a mass matching 180 — an inconsistent scale-up.", "misconceptionId": "formula_recall_error"}, {"option": "E", "explanation": "C4H8O4 keeps the 1:2:1 ratio but only reaches RMM 120, short of the required 180.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$The molecular formula of X is$q$, $q$[{"label": "A", "text": "C12H22O11", "isCorrect": false}, {"label": "B", "text": "C6H12O6", "isCorrect": true}, {"label": "C", "text": "C3H6O3", "isCorrect": false}, {"label": "D", "text": "C7H14O7", "isCorrect": false}, {"label": "E", "text": "C4H8O4", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Same compound X from the passage above (glucose). C:H:O ratio 1:2:1 with RMM 180 fixes the formula directly — C6H12O6 fits both the ratio and the molar mass (72+12+96=180). This is the same reasoning you'd use any time you're given a ratio and a molar mass together: find the empirical formula from the ratio, then scale it up until the mass matches.$q$, $q$live$q$, $q$A: C12H22O11 is sucrose's formula (RMM 342), not a 1:2:1 ratio compound with RMM 180 — this is a distractor swapping in a different, related sugar. C: C3H6O3 keeps the correct 1:2:1 ratio but only has RMM 90 — half of the required 180, so the scaling step was stopped too early. D: C7H14O7 does not actually keep a clean 1:2:1 C:H:O ratio at a mass matching 180 — an inconsistent scale-up. E: C4H8O4 keeps the 1:2:1 ratio but only reaches RMM 120, short of the required 180.$q$),
($q$chemistry_0210$q$, $q$Chemistry$q$, $q$Chemistry & Industry$q$, $q$Fermentation and Brewing$q$, $q$Identify the industry built on yeast fermentation of sugar.$q$, $q$[{"conceptId": "pfpi8t", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "The plastic industry relies on polymerization of monomers, not yeast fermentation of a sugar.", "misconceptionId": "memorized_not_understood"}, {"option": "B", "explanation": "The textile industry works with fibres and dyes, not the ethanol/CO2 products of yeast fermentation.", "misconceptionId": "memorized_not_understood"}, {"option": "D", "explanation": "The soap industry relies on fat/oil hydrolysis by an alkali (saponification), a completely different reaction from yeast fermentation.", "misconceptionId": "confused_similar_concepts"}, {"option": "E", "explanation": "The dyeing industry works with colourants, unrelated to yeast turning sugar into ethanol.", "misconceptionId": "memorized_not_understood"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$Reaction of X with yeast forms the basis of the$q$, $q$[{"label": "A", "text": "plastic industry", "isCorrect": false}, {"label": "B", "text": "textile industry", "isCorrect": false}, {"label": "C", "text": "brewing industry", "isCorrect": true}, {"label": "D", "text": "soap industry", "isCorrect": false}, {"label": "E", "text": "dyeing industry", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Yeast fermenting a sugar into ethanol and CO2 is literally how alcoholic drinks are brewed — that's the industrial application this fact is pointing at.$q$, $q$live$q$, $q$A: The plastic industry relies on polymerization of monomers, not yeast fermentation of a sugar. B: The textile industry works with fibres and dyes, not the ethanol/CO2 products of yeast fermentation. D: The soap industry relies on fat/oil hydrolysis by an alkali (saponification), a completely different reaction from yeast fermentation. E: The dyeing industry works with colourants, unrelated to yeast turning sugar into ethanol.$q$),
($q$chemistry_0211$q$, $q$Chemistry$q$, $q$Separation of Mixtures$q$, $q$Separation Techniques$q$, $q$Choose the correct order of separation techniques for a three-component solid mixture.$q$, $q$[{"conceptId": "kc1jua", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 80, $q$medium$q$, $q$none$q$, $q$[{"option": "A", "explanation": "This dissolves the mixture in water before sublimation is attempted — but sublimation needs a dry solid, and adding water first defeats that step entirely.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "This does sublimation after wetting the mixture, which also defeats sublimation's requirement of a dry solid — the steps are in a workable order but at the wrong starting point.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Fractional distillation separates miscible liquids by boiling point — nothing here is a liquid mixture, so this technique doesn't apply.", "misconceptionId": "confused_similar_concepts"}, {"option": "E", "explanation": "Fractional crystallization separates solutes by differing solubility as a solution cools — it doesn't handle an insoluble solid like BaSO4 or a subliming solid like NH4Cl.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$A mixture of common salt, ammonium chloride and barium sulphate can best be separated by$q$, $q$[{"label": "A", "text": "addition of water followed by filtration then sublimation", "isCorrect": false}, {"label": "B", "text": "addition of water followed by sublimation then filtration", "isCorrect": false}, {"label": "C", "text": "sublimation followed by addition of water then filtration", "isCorrect": true}, {"label": "D", "text": "fractional distillation", "isCorrect": false}, {"label": "E", "text": "fractional crystallization", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Think about which property you're using at each step, in order. Ammonium chloride sublimes directly from the solid — so heat the dry mixture first and NH4Cl leaves as vapour, no water needed for that step. What's left is NaCl and BaSO4 solid. Now add water: NaCl dissolves, BaSO4 doesn't (it's insoluble). Filter, and BaSO4 stays on the paper while NaCl solution passes through. Three different properties, three matched steps, in the right order — that's the whole logic of a separation question like this.$q$, $q$live$q$, $q$A: This dissolves the mixture in water before sublimation is attempted — but sublimation needs a dry solid, and adding water first defeats that step entirely. B: This does sublimation after wetting the mixture, which also defeats sublimation's requirement of a dry solid — the steps are in a workable order but at the wrong starting point. D: Fractional distillation separates miscible liquids by boiling point — nothing here is a liquid mixture, so this technique doesn't apply. E: Fractional crystallization separates solutes by differing solubility as a solution cools — it doesn't handle an insoluble solid like BaSO4 or a subliming solid like NH4Cl.$q$),
($q$chemistry_0212$q$, $q$Chemistry$q$, $q$Kinetic Theory & Gas Laws$q$, $q$Gas Laws$q$, $q$Identify the correct proportionality relating pressure, volume and temperature for an ideal gas.$q$, $q$[{"conceptId": "84csd7", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 45, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "P ∝ VT would come from rearranging PV=nRT as P = nRT/V, then mistakenly moving V to the numerator instead of leaving it in the denominator.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "This states three quantities are all simply proportional to each other without expressing the actual inverse relationship between P and V — too vague to be the ideal gas law.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "P ∝ V/T inverts the correct relationship — P actually increases with T and decreases with V, the opposite of what this option states.", "misconceptionId": "sign_error"}, {"option": "E", "explanation": "This proposes PV ∝ VT, which doesn't reduce to anything consistent with PV=nRT at constant n and R.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$Which of the following relationships between the pressure P, the volume V and the temperature T, represents an ideal gas behaviour?$q$, $q$[{"label": "A", "text": "P & VT", "isCorrect": false}, {"label": "B", "text": "P & T/V", "isCorrect": true}, {"label": "C", "text": "P & T & V", "isCorrect": false}, {"label": "D", "text": "P & V/T", "isCorrect": false}, {"label": "E", "text": "PV & VT", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Start from PV = nRT, and hold n and R constant. Rearranged, P = (nR)(T/V) — pressure is proportional to temperature divided by volume. That's the relationship you're being asked to spot: P varies directly with T and inversely with V, together.$q$, $q$live$q$, $q$A: P ∝ VT would come from rearranging PV=nRT as P = nRT/V, then mistakenly moving V to the numerator instead of leaving it in the denominator. C: This states three quantities are all simply proportional to each other without expressing the actual inverse relationship between P and V — too vague to be the ideal gas law. D: P ∝ V/T inverts the correct relationship — P actually increases with T and decreases with V, the opposite of what this option states. E: This proposes PV ∝ VT, which doesn't reduce to anything consistent with PV=nRT at constant n and R.$q$),
($q$chemistry_0213$q$, $q$Chemistry$q$, $q$Metals & Their Compounds$q$, $q$Flame Tests$q$, $q$Recall the flame test colour for the calcium ion.$q$, $q$[{"conceptId": "865p59", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Green is copper's flame colour, not calcium's.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Blue-green shading is associated with copper, not calcium.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Yellow is sodium's flame colour, one of the most commonly confused with calcium's brick-red.", "misconceptionId": "confused_similar_concepts"}, {"option": "E", "explanation": "Lilac is potassium's flame colour, not calcium's.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$The colour imparted to a flame by calcium ion is$q$, $q$[{"label": "A", "text": "green", "isCorrect": false}, {"label": "B", "text": "blue", "isCorrect": false}, {"label": "C", "text": "brick-red", "isCorrect": true}, {"label": "D", "text": "yellow", "isCorrect": false}, {"label": "E", "text": "lilac", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Flame colours are a straight memory item, but it helps to anchor them: sodium is yellow, potassium is lilac, calcium is brick-red, copper is green/blue-green. If you keep mixing these up, group them by how "warm" or "cool" the colour feels — calcium and strontium give warm reds, copper gives cool greens.$q$, $q$live$q$, $q$A: Green is copper's flame colour, not calcium's. B: Blue-green shading is associated with copper, not calcium. D: Yellow is sodium's flame colour, one of the most commonly confused with calcium's brick-red. E: Lilac is potassium's flame colour, not calcium's.$q$),
($q$chemistry_0214$q$, $q$Chemistry$q$, $q$Oxidation & Reduction$q$, $q$Identifying Oxidation from Equations$q$, $q$Track an element's oxidation number across four reactions to identify which involve oxidation.$q$, $q$[{"conceptId": "3hq7md", "weight": 1}]$q$::jsonb, 3, $q$analysis$q$, 80, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Reaction (1) is correctly identified, but reaction (3) also shows iron being oxidized (+2 to +3) and was left out.", "misconceptionId": "missing_prerequisite"}, {"option": "B", "explanation": "Reaction (2) shows iron staying at +2 throughout — no oxidation happens there at all.", "misconceptionId": "misread_graph"}, {"option": "C", "explanation": "Reaction (3) is correctly identified, but reaction (1) (Fe going from 0 to +2) also shows oxidation and was left out.", "misconceptionId": "missing_prerequisite"}, {"option": "E", "explanation": "Reaction (2) shows no change in iron's oxidation number, and reaction (4) shows iron being REDUCED (+3 to +2), not oxidized — both picks are wrong.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$In which of the following processes is iron being oxidized? 1. Fe + H2SO4 → H2 + FeSO4  2. FeSO4 + H2S → FeS + H2SO4  3. FeCl2 + Cl2 → 2FeCl3  4. FeCl3 + SnCl2 → 2FeCl2 + SnCl4$q$, $q$[{"label": "A", "text": "1 only", "isCorrect": false}, {"label": "B", "text": "2 only", "isCorrect": false}, {"label": "C", "text": "3 only", "isCorrect": false}, {"label": "D", "text": "1 and 3", "isCorrect": true}, {"label": "E", "text": "2 and 4", "isCorrect": false}]$q$::jsonb, $q$D$q$, $q$Don't look for a single reaction type — track iron's oxidation number in each one. In (1), Fe goes from 0 to +2: oxidized. In (2), Fe stays at +2 on both sides: no change. In (3), Fe goes from +2 to +3: oxidized. In (4), Fe actually goes from +3 down to +2: that's reduction, not oxidation, even though it looks like a similar reaction to (3). Oxidation numbers going up, every time — that's the only rule that matters here.$q$, $q$live$q$, $q$A: Reaction (1) is correctly identified, but reaction (3) also shows iron being oxidized (+2 to +3) and was left out. B: Reaction (2) shows iron staying at +2 throughout — no oxidation happens there at all. C: Reaction (3) is correctly identified, but reaction (1) (Fe going from 0 to +2) also shows oxidation and was left out. E: Reaction (2) shows no change in iron's oxidation number, and reaction (4) shows iron being REDUCED (+3 to +2), not oxidized — both picks are wrong.$q$),
($q$chemistry_0215$q$, $q$Chemistry$q$, $q$Metals & Their Compounds$q$, $q$Reactivity and Electrochemical Series$q$, $q$Explain why iron displaces copper from copper(II) ion solution.$q$, $q$[{"conceptId": "e6wz62", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 40, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Both metals start in different states in every displacement reaction by definition — that's just restating the setup, not explaining WHY the displacement happens.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "Atomic weight has no bearing on which metal displaces which — that's decided by reactivity (electrochemical series position), not mass.", "misconceptionId": "overgeneralized_rule"}, {"option": "C", "explanation": "Number of electrons in a metal atom doesn't determine reactivity by itself — this is a plausible-sounding but chemically irrelevant explanation.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Iron is not inert — quite the opposite, it's reactive enough to actively displace copper from solution here.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$In the reaction Fe + Cu2+ → Fe2+ + Cu, iron displaces copper ions to form copper. This is due to the fact that$q$, $q$[{"label": "A", "text": "iron is in the metallic form while the copper is in the ionic form", "isCorrect": false}, {"label": "B", "text": "the atomic weight of copper is greater than that of iron", "isCorrect": false}, {"label": "C", "text": "copper metal has more electrons than iron metal", "isCorrect": false}, {"label": "D", "text": "iron is an inert metal", "isCorrect": false}, {"label": "E", "text": "iron is higher in the electrochemical series than copper", "isCorrect": true}]$q$::jsonb, $q$E$q$, $q$Displacement reactions come down to one thing: position in the electrochemical (reactivity) series. A more reactive metal, higher up the series, will always push a less reactive metal's ions back to the solid metal, giving up its own electrons in the process. Iron sits above copper, so it displaces it — that's the whole reason, not the physical states or atomic weights mentioned in the other options.$q$, $q$live$q$, $q$A: Both metals start in different states in every displacement reaction by definition — that's just restating the setup, not explaining WHY the displacement happens. B: Atomic weight has no bearing on which metal displaces which — that's decided by reactivity (electrochemical series position), not mass. C: Number of electrons in a metal atom doesn't determine reactivity by itself — this is a plausible-sounding but chemically irrelevant explanation. D: Iron is not inert — quite the opposite, it's reactive enough to actively displace copper from solution here.$q$),
($q$chemistry_0216$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Isomerism$q$, $q$Enumerate all structural isomers of a dihalogenated propane.$q$, $q$[{"conceptId": "j32bof", "weight": 1}]$q$::jsonb, 3, $q$analysis$q$, 75, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This misses that bromine's position along the 3-carbon chain can vary in several genuinely different ways, not just one.", "misconceptionId": "missing_prerequisite"}, {"option": "B", "explanation": "This stops the systematic placement too early — only two of the four real positional arrangements were counted.", "misconceptionId": "missing_prerequisite"}, {"option": "C", "explanation": "This is close but still misses one valid arrangement (either 1,3- or 2,2-dibromopropane was left out).", "misconceptionId": "missing_prerequisite"}, {"option": "E", "explanation": "This overcounts — one of the five 'positions' considered is not actually a distinct structure once the symmetry of the propane chain is accounted for.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$How many isomeric forms are there for the molecular formula C3H6Br2?$q$, $q$[{"label": "A", "text": "1", "isCorrect": false}, {"label": "B", "text": "2", "isCorrect": false}, {"label": "C", "text": "3", "isCorrect": false}, {"label": "D", "text": "4", "isCorrect": true}, {"label": "E", "text": "5", "isCorrect": false}]$q$::jsonb, $q$D$q$, $q$Place the two bromines on the three-carbon chain in every position that gives a genuinely different structure: both on C1 (1,1-dibromopropane), one on C1 and one on C2 (1,2-), one on C1 and one on C3 (1,3-), or both on C2 (2,2-). That's four distinct structural isomers. The habit worth building here: draw the carbon skeleton first, then systematically move the substituents one position at a time rather than trying to picture them all at once.$q$, $q$live$q$, $q$A: This misses that bromine's position along the 3-carbon chain can vary in several genuinely different ways, not just one. B: This stops the systematic placement too early — only two of the four real positional arrangements were counted. C: This is close but still misses one valid arrangement (either 1,3- or 2,2-dibromopropane was left out). E: This overcounts — one of the five 'positions' considered is not actually a distinct structure once the symmetry of the propane chain is accounted for.$q$),
($q$chemistry_0217$q$, $q$Chemistry$q$, $q$Non-Metals & Their Compounds$q$, $q$Sulphur Compounds$q$, $q$Identify the acid formed when burning sulphur's fumes dissolve in water.$q$, $q$[{"conceptId": "2eamtt", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 70, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "\"Sulphur (IV) trioxide\" isn't even valid IUPAC naming for a real compound (a trioxide would be an SO3-type species, but named with a IV oxidation state it's internally inconsistent) — a distractor built to look technical rather than a real product.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Trioxosulphate (IV) acid is sulphurous acid (H2SO3, from SO2) — the product of LIMITED oxygen, not the sustained, excess-oxygen burning this question describes.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "\"Dioxosulphate (II) acid\" doesn't correspond to a real, common sulphur oxoacid — a plausible-sounding but non-existent name.", "misconceptionId": "memorized_not_understood"}, {"option": "E", "explanation": "Hydrogen sulphide (H2S) is a foul-smelling reducing gas unrelated to sulphur burning in oxygen — a completely different sulphur compound.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$A piece of burning sulphur will continue to burn in a gas jar of oxygen to give misty fumes which readily dissolve in water. The resulting liquid is$q$, $q$[{"label": "A", "text": "sulphur (IV) trioxide", "isCorrect": false}, {"label": "B", "text": "Tetraoxosulphate acid (VI)", "isCorrect": true}, {"label": "C", "text": "Trioxosulphate (IV) acid", "isCorrect": false}, {"label": "D", "text": "Dioxosulphate (II) acid", "isCorrect": false}, {"label": "E", "text": "Hydrogen sulphide", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Sustained burning of sulphur in excess oxygen pushes the reaction past SO2 to SO3, and SO3 dissolving in water is exactly how tetraoxosulphate (VI) acid — ordinary sulphuric acid — forms. "Misty fumes that dissolve readily" is describing SO3 gas meeting water vapour, not the simpler SO2 you'd get from limited oxygen.$q$, $q$live$q$, $q$A: "Sulphur (IV) trioxide" isn't even valid IUPAC naming for a real compound (a trioxide would be an SO3-type species, but named with a IV oxidation state it's internally inconsistent) — a distractor built to look technical rather than a real product. C: Trioxosulphate (IV) acid is sulphurous acid (H2SO3, from SO2) — the product of LIMITED oxygen, not the sustained, excess-oxygen burning this question describes. D: "Dioxosulphate (II) acid" doesn't correspond to a real, common sulphur oxoacid — a plausible-sounding but non-existent name. E: Hydrogen sulphide (H2S) is a foul-smelling reducing gas unrelated to sulphur burning in oxygen — a completely different sulphur compound.$q$),
($q$chemistry_0218$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Hydrates and Water of Crystallization$q$, $q$Name the process by which a hydrate loses all its water of crystallization to the air.$q$, $q$[{"conceptId": "sdx4xa", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 30, $q$low$q$, $q$none$q$, $q$[{"option": "B", "explanation": "Hygroscopic describes a solid ABSORBING moisture from the air, the opposite direction of water movement from what's described here.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Deliquescence is a solid absorbing so much water it dissolves into a solution — again the opposite direction from a hydrate losing its own water.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Effervescence is the bubbling release of a gas (like CO2 from a carbonate), not the loss of water of crystallization.", "misconceptionId": "misunderstood_terminology"}, {"option": "E", "explanation": "Dehydration is a broader, more general term for water removal (often driven, e.g. by heating) — efflorescence is the specific name for this happening spontaneously to a hydrate at room temperature.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$Sodium decahydrate (Na2SO4.10H2O) on exposure to air loses all its water of crystallization. The process of loss is known as$q$, $q$[{"label": "A", "text": "Efflorescence", "isCorrect": true}, {"label": "B", "text": "Hygroscopy", "isCorrect": false}, {"label": "C", "text": "Deliquescence", "isCorrect": false}, {"label": "D", "text": "Effervescence", "isCorrect": false}, {"label": "E", "text": "Dehydration", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Keep these three apart by what actually happens to the solid: efflorescence is a hydrate losing its own water of crystallization to the air and crumbling to powder; deliquescence is a solid absorbing so much moisture from the air it dissolves into a solution; hygroscopic just means something absorbs moisture without necessarily dissolving. Losing water TO the air, from a hydrate — that's efflorescence.$q$, $q$live$q$, $q$B: Hygroscopic describes a solid ABSORBING moisture from the air, the opposite direction of water movement from what's described here. C: Deliquescence is a solid absorbing so much water it dissolves into a solution — again the opposite direction from a hydrate losing its own water. D: Effervescence is the bubbling release of a gas (like CO2 from a carbonate), not the loss of water of crystallization. E: Dehydration is a broader, more general term for water removal (often driven, e.g. by heating) — efflorescence is the specific name for this happening spontaneously to a hydrate at room temperature.$q$),
($q$chemistry_0219$q$, $q$Chemistry$q$, $q$Electrolysis$q$, $q$Electrode Reactions$q$, $q$Identify which half-reaction correctly describes electrolysis of molten sodium chloride.$q$, $q$[{"conceptId": "23bs2u", "weight": 1}]$q$::jsonb, 3, $q$analysis$q$, 75, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Sodium ion GAINS an electron at the cathode (it's reduced to Na metal) — it doesn't lose one.", "misconceptionId": "sign_error"}, {"option": "B", "explanation": "There's no free chlorine atom involved before the reaction — chloride ION loses an electron at the anode; a neutral chlorine atom 'gaining' an electron isn't what's happening here.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Chloride ion LOSES an electron at the anode (it's oxidized to Cl2) — it doesn't gain one.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "Sodium ion is REDUCED at the cathode (it gains an electron to become Na metal), not oxidized.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$Which of the following happens during the electrolysis of molten sodium chloride?$q$, $q$[{"label": "A", "text": "Sodium ion loses an electron", "isCorrect": false}, {"label": "B", "text": "Chlorine atom gains an electron", "isCorrect": false}, {"label": "C", "text": "Chloride ion gains an electron", "isCorrect": false}, {"label": "D", "text": "Sodium ion is oxidized", "isCorrect": false}, {"label": "E", "text": "Chloride ion is oxidized", "isCorrect": true}]$q$::jsonb, $q$E$q$, $q$At the cathode, Na+ gains an electron and is reduced to Na metal. At the anode, Cl- loses an electron and is oxidized to Cl2 gas. So sodium ion is reduced (not oxidized, ruling out D), and chloride ion is oxidized by losing an electron, not gaining one — that's E. The trap here is remembering which electrode does which: cathode reduces, anode oxidizes, always.$q$, $q$live$q$, $q$A: Sodium ion GAINS an electron at the cathode (it's reduced to Na metal) — it doesn't lose one. B: There's no free chlorine atom involved before the reaction — chloride ION loses an electron at the anode; a neutral chlorine atom 'gaining' an electron isn't what's happening here. C: Chloride ion LOSES an electron at the anode (it's oxidized to Cl2) — it doesn't gain one. D: Sodium ion is REDUCED at the cathode (it gains an electron to become Na metal), not oxidized.$q$),
($q$chemistry_0220$q$, $q$Chemistry$q$, $q$Environmental Pollution$q$, $q$Pollution Control$q$, $q$Identify the practical method for dispersing an oil spill on water.$q$, $q$[{"conceptId": "alfbvy", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 50, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Heating an open waterway to boil off petroleum isn't a practical real-world method — it's impractical at the scale of a creek and doesn't match how spills are actually handled.", "misconceptionId": "memorized_not_understood"}, {"option": "B", "explanation": "Petroleum doesn't dissolve in water at all — stirring cannot make an insoluble liquid dissolve, no matter how vigorous.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Pouring more organic solvents onto a waterway would add another pollutant rather than remove one — not the real dispersal method used.", "misconceptionId": "overgeneralized_rule"}, {"option": "E", "explanation": "Cooling a large open waterway to freeze out petroleum isn't practical or how real spills are managed.", "misconceptionId": "memorized_not_understood"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$Crude petroleum pollutant usually seen on some Nigerian creeks and waterways can be dispersed or removed by$q$, $q$[{"label": "A", "text": "heating the affected parts in order to boil off the petroleum", "isCorrect": false}, {"label": "B", "text": "mechanically stirring to dissolve the petroleum in water", "isCorrect": false}, {"label": "C", "text": "pouring organic solvents to dissolve the petroleum", "isCorrect": false}, {"label": "D", "text": "spraying the water with detergents", "isCorrect": true}, {"label": "E", "text": "cooling to freeze out the petroleum", "isCorrect": false}]$q$::jsonb, $q$D$q$, $q$Oil doesn't dissolve in water no matter how much you stir it — that option is a distractor built on a wrong assumption. Detergents work because they're surfactants: they break the oil slick into tiny droplets that disperse into the water column, which is the real-world method used on oil spills.$q$, $q$live$q$, $q$A: Heating an open waterway to boil off petroleum isn't a practical real-world method — it's impractical at the scale of a creek and doesn't match how spills are actually handled. B: Petroleum doesn't dissolve in water at all — stirring cannot make an insoluble liquid dissolve, no matter how vigorous. C: Pouring more organic solvents onto a waterway would add another pollutant rather than remove one — not the real dispersal method used. E: Cooling a large open waterway to freeze out petroleum isn't practical or how real spills are managed.$q$),
($q$chemistry_0221$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Electronegativity$q$, $q$Define electronegativity in terms of electron gain/loss tendency.$q$, $q$[{"conceptId": "3a2yze", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Physical state (gas/liquid/solid) has nothing to do with an element's electron-gaining tendency — an unrelated property used as a distractor.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "Solubility of an element's ions doesn't define electronegativity — a plausible-sounding but unrelated property.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "'Tendency to lose electrons' describes electroPOSITIVE, the direct opposite of electronegative.", "misconceptionId": "confused_similar_concepts"}, {"option": "E", "explanation": "Forming covalent bonds involves SHARING electrons between two atoms, which isn't the same definition as one atom's individual tendency to gain electrons.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$An element is electronegative if$q$, $q$[{"label": "A", "text": "it has a tendency to exist in the gaseous form", "isCorrect": false}, {"label": "B", "text": "its ions dissolve readily in water", "isCorrect": false}, {"label": "C", "text": "it has a tendency to lose electrons", "isCorrect": false}, {"label": "D", "text": "it has a tendency to gain electrons", "isCorrect": true}, {"label": "E", "text": "it readily forms covalent bonds", "isCorrect": false}]$q$::jsonb, $q$D$q$, $q$Electronegativity is about pulling electrons toward yourself — so an electronegative element wants to gain (or attract) electrons, not lose them. That's the direct opposite of an electropositive element, which readily loses electrons. Keep the two terms pinned to opposite directions and this type of question stops being confusing.$q$, $q$live$q$, $q$A: Physical state (gas/liquid/solid) has nothing to do with an element's electron-gaining tendency — an unrelated property used as a distractor. B: Solubility of an element's ions doesn't define electronegativity — a plausible-sounding but unrelated property. C: 'Tendency to lose electrons' describes electroPOSITIVE, the direct opposite of electronegative. E: Forming covalent bonds involves SHARING electrons between two atoms, which isn't the same definition as one atom's individual tendency to gain electrons.$q$),
($q$chemistry_0222$q$, $q$Chemistry$q$, $q$Acids, Bases & Salts$q$, $q$pH Scale$q$, $q$Compare the relative acidity of three solutions given their pH values.$q$, $q$[{"conceptId": "ab1gw8", "weight": 1}]$q$::jsonb, 2, $q$analysis$q$, 55, $q$medium$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Z has pH 9, above the neutral point of 7 — it's basic, not acidic, so not all three solutions are acidic.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "X (pH 3) and Y (pH 5) are both below 7 and are acidic, not basic — only Z is basic.", "misconceptionId": "overgeneralized_rule"}, {"option": "C", "explanation": "Pure water sits at pH 7 — Y (pH 5) and Z (pH 9) are on opposite sides of neutral, so they can't both be described as 'more acidic than water'.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Y has the HIGHER pH of the two (5 vs 3), and higher pH means LESS acidic — so Y is actually less acidic than X, the reverse of this statement.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$jamb_past_question$q$, 1983, $q$JAMB$q$, $q$Solutions X, Y, and Z have pH values 3.0, 5.0 and 9.0 respectively. Which of the following statements is correct?$q$, $q$[{"label": "A", "text": "All the solutions are acidic", "isCorrect": false}, {"label": "B", "text": "All solutions are basic", "isCorrect": false}, {"label": "C", "text": "Y and Z are more acidic than water", "isCorrect": false}, {"label": "D", "text": "Y is more acidic than X", "isCorrect": false}, {"label": "E", "text": "Z is the least acidic", "isCorrect": true}]$q$::jsonb, $q$E$q$, $q$The one thing to hold onto with pH: lower number means more acidic, not less. X (pH 3) is the most acidic of the three. Z (pH 9) is above 7, so it's actually basic, not acidic at all — which makes it the "least acidic" by default. Don't let the direction of the pH scale trip you up; it runs backwards from what feels intuitive at first.$q$, $q$live$q$, $q$A: Z has pH 9, above the neutral point of 7 — it's basic, not acidic, so not all three solutions are acidic. B: X (pH 3) and Y (pH 5) are both below 7 and are acidic, not basic — only Z is basic. C: Pure water sits at pH 7 — Y (pH 5) and Z (pH 9) are on opposite sides of neutral, so they can't both be described as 'more acidic than water'. D: Y has the HIGHER pH of the two (5 vs 3), and higher pH means LESS acidic — so Y is actually less acidic than X, the reverse of this statement.$q$);
